}

.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -3rem;
  padding: 0.5rem 0.75rem;
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 0.5rem; }

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: rgba(11, 13, 18, 0.7);
  backdrop-filter: blur(8px);
}

.brand {
  font-weight: 600;
  letter-spacing: 0.02em;
}

.primary-nav {
  display: flex;
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.primary-nav a {
  color: var(--text-muted);
  text-decoration: none;
  padding: 0.35rem 0.5rem;
  border-radius: 6px;
}
.primary-nav a:hover { color: var(--text); }
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev-2);
}

main {
  max-width: 880px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

h1 {
  margin: 0 0 1.25rem;
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  font-weight: 600;
  letter-spacing: -0.01em;
}

.preview {
  margin: 0 0 1.25rem;
  background: var(--bg-elev-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}

.preview img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.preview figcaption {
  padding: 0.75rem 1rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: flex-end;
}

.btn {
  appearance: none;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  padding: 0.6rem 1.1rem;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  transition: background-color 0.15s, border-color 0.15s, transform 0.05s;
}
.btn:hover { background: #242a3d; }
.btn:active { transform: translateY(1px); }

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-secondary { /* default */ }

.btn-danger {
  background: var(--danger-bg);
  border-color: #6a2330;
  color: var(--danger-strong);
}
.btn-danger:hover {
  background: #4a1a26;
  border-color: var(--danger);
  color: #fff;
}

/* Dialog */
.confirm-dialog {
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-1);
  color: var(--text);
  border-radius: var(--radius);
  padding: 0;
  width: min(440px, calc(100% - 2rem));
  box-shadow: var(--shadow);
}

.confirm-dialog::backdrop {
  background: rgba(5, 7, 12, 0.65);
  backdrop-filter: blur(4px);
}

/* Open animation */
.confirm-dialog[open] {
  animation: dialog-in 160ms ease-out;
}
.confirm-dialog[open]::backdrop {
  animation: backdrop-in 160ms ease-out;
}

@keyframes dialog-in {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
@keyframes backdrop-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .confirm-dialog[open],
  .confirm-dialog[open]::backdrop { animation: none; }
}

.confirm-dialog__form {
  padding: 1.5rem 1.5rem 1.25rem;
  margin: 0;
}

.confirm-dialog__title {
  margin: 0 0 0.5rem;
  font-size: 1.15rem;
  font-weight: 600;
}

.confirm-dialog__body {
  margin: 0 0 1.25rem;
  color: var(--text-muted);
}

.confirm-dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
}

/* Status (live region) */
.status {
  position: fixed;
  inset-inline: 0;
  bottom: 1.25rem;
  margin: 0 auto;
  width: max-content;
  max-width: calc(100% - 2rem);
  padding: 0.6rem 1rem;
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  box-shadow: var(--shadow);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.2s, transform 0.2s;
  pointer-events: none;
}
.status.is-visible {
  opacity: 1;
  transform: none;
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .confirm-dialog { border: 1px solid CanvasText; }
  .btn:focus-visible { outline: 2px solid Highlight; }
}

@media (max-width: 480px) {
  .actions { justify-content: stretch; }
  .actions .btn { flex: 1; }
}
