  const url = 'file://' + path.resolve(__dirname, 'index.html');
  await page.goto(url, { waitUntil: 'networkidle0' });

  const closed = await new AxePuppeteer(page).analyze();
  console.log('--- Closed state ---');
  console.log(JSON.stringify(closed.violations, null, 2));

  await page.click('#delete-trigger');
  await new Promise(r => setTimeout(r, 300));

  const open = await new AxePuppeteer(page).analyze();
  console.log('--- Open state ---');
  console.log(JSON.stringify(open.violations, null, 2));

