+const fs = require('fs');
+const path = require('path');
+const { JSDOM } = require('jsdom');
+const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
+
+(async () => {
+  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
+  const css = fs.readFileSync(path.join(__dirname, 'styles.css'), 'utf8');
+  const inlined = html.replace(
+    /<link rel="stylesheet" href="styles\.css"[^>]*>/,
+    `<style>${css}</style>`
+  );
+
+  const dom = new JSDOM(inlined, {
+    runScripts: 'dangerously',
+    pretendToBeVisual: true,
+    url: 'file://' + path.join(__dirname, 'index.html'),
+  });
+  const { window } = dom;
+  await new Promise(r => window.addEventListener('load', r));
+  window.eval(axeSource);
+
+  async function run(label) {
+    const results = await window.axe.run(window.document, { resultTypes: ['violations'] });
+    console.log(`--- ${label} ---`);
+    if (!results.violations.length) console.log('No violations.');
+    for (const v of results.violations) {
+      console.log(`[${v.impact}] ${v.id}: ${v.help}`);
+      for (const n of v.nodes) console.log('  -', n.target.join(' '));
+    }
+    return results.violations.length;
+  }
+
+  let total = 0;
+  total += await run('Closed state');
+
+  const trigger = window.document.getElementById('delete-trigger');
+  const dialog = window.document.getElementById('delete-dialog');
+  if (typeof dialog.showModal !== 'function') {
+    dialog.showModal = function () { this.setAttribute('open', ''); };
+    dialog.close = function (v) { this.removeAttribute('open'); this.returnValue = v || ''; this.dispatchEvent(new window.Event('close')); };
+  }
+  trigger.click();
+  await new Promise(r => setTimeout(r, 100));
+  total += await run('Open state');
+
+  process.exit(total > 0 ? 1 : 0);
+})();
+
')
